// Expo config plugin: signs Android release builds with the upload keystore
// described in <project root>/keystore.properties (created by
// scripts/buildAndroidRelease.js, gitignored). android/ is generated by
// `expo prebuild`, so the signing config is injected here rather than edited
// into android/app/build.gradle by hand, where the next prebuild would wipe it.
//
// Without keystore.properties, release builds fall back to the debug key
// (fine for local testing, rejected by the Play Store).
const { withAppBuildGradle } = require("expo/config-plugins");

const MARKER = "// @generated withReleaseSigning";

const PROPS_LOADER = `${MARKER}
def releaseKeystorePropsFile = rootProject.file("../keystore.properties")
def releaseKeystoreProps = new Properties()
if (releaseKeystorePropsFile.exists()) {
    releaseKeystorePropsFile.withInputStream { releaseKeystoreProps.load(it) }
}

android {`;

const RELEASE_SIGNING_CONFIG = `signingConfigs {
        release {
            if (releaseKeystorePropsFile.exists()) {
                storeFile rootProject.file("../" + releaseKeystoreProps["storeFile"])
                storePassword releaseKeystoreProps["storePassword"]
                keyAlias releaseKeystoreProps["keyAlias"]
                keyPassword releaseKeystoreProps["keyPassword"]
            }
        }`;

function addReleaseSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  let out = gradle.replace(/^android \{/m, PROPS_LOADER);
  out = out.replace(/signingConfigs \{/, RELEASE_SIGNING_CONFIG);
  // Only the release buildType's line: it's the one after `release {` inside
  // buildTypes (the debug buildType keeps the debug key).
  out = out.replace(
    /(buildTypes \{[\s\S]*?release \{[\s\S]*?)signingConfig signingConfigs\.debug/,
    "$1signingConfig releaseKeystorePropsFile.exists() ? signingConfigs.release : signingConfigs.debug",
  );

  if (
    !out.includes(MARKER) ||
    !out.includes("storeFile rootProject.file") ||
    !out.includes("signingConfigs.release : signingConfigs.debug")
  ) {
    throw new Error(
      "withReleaseSigning: android/app/build.gradle no longer has the expected shape; update plugins/withReleaseSigning.js.",
    );
  }
  return out;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== "groovy") {
      throw new Error("withReleaseSigning only supports a Groovy build.gradle");
    }
    cfg.modResults.contents = addReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.addReleaseSigning = addReleaseSigning;
